mapper.update:
update t_order_idempotency
set status = 'EXPIRED',
    update_time = #{now}
where user_id = #{userId}
  and idempotency_key = #{idempotencyKey}
  and status = 'ISSUED'
  and expires_at < #{now}

mapper.delete:
delete from t_order_idempotency
where status in ('ISSUED', 'EXPIRED')
  and expires_at < #{cutoff}
